+export function StudioShell() {
+  return (
+    <div className="studio-app">
+      <SettingsPanel />
+      <StudioHeader />
+      <div className="studio-layout">
+        <CanvasTabs />
+        <ChatCopilot />
+      </div>
+      <Toasts />
