+}
+
+.studio-header__title {
+  font-size: 1.5rem;
+  font-weight: 700;
+  letter-spacing: -0.02em;
+}
+
+.studio-header__title span {
+  opacity: 0.5;
+  font-size: 1rem;
+  font-weight: 400;
+}
+
+.studio-header__subtitle {
+  font-size: 0.85rem;
+  color: var(--studio-muted);
+  margin-top: 2px;
+}
+
+.studio-header__pills {
+  display: flex;
+  gap: 6px;
+  flex-wrap: wrap;
+  justify-content: flex-end;
+}
+
+.studio-pill {
